WITH lines AS (SELECT id, plan, effective_from, currency, EXPLODE(tier_limits) AS tier_value FROM price_tiers), base AS (SELECT id, plan, currency, tier_value, LAST_DAY(effective_from) effective_from_month_end FROM lines WHERE effective_from > DATE '2024-06-05'), enriched AS (SELECT id, plan, currency, tier_value, effective_from_month_end, RANK() OVER (PARTITION BY currency ORDER BY tier_value DESC) tier_value_rank, CUME_DIST() OVER (PARTITION BY currency ORDER BY tier_value) tier_value_cume_dist FROM base) SELECT CASE WHEN tier_value >= 81 THEN 'PREMIUM' ELSE 'STANDARD' END AS tier_value_tier, CASE WHEN tier_value_rank >= 9 THEN 'LARGE' ELSE 'SMALL' END AS tier_value_rank_tier, plan, COUNT_IF(plan = 'basic') AS basic_events, APPROX_PERCENTILE(tier_value_cume_dist, 0.9) AS tier_value_cume_dist_p90, COUNT(CASE WHEN plan = 'starter' THEN 1 END) AS starter_count FROM enriched GROUP BY CASE WHEN tier_value >= 81 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN tier_value_rank >= 9 THEN 'LARGE' ELSE 'SMALL' END, plan
